R=[
(2918,"एप्पल साइडर बीफ़ स्ट्यू","सेब, एप्पल साइडर और एप्पल साइडर सिरका इस स्ट्यू में मीठा स्वाद जोड़ते हैं। किडनी के अनुकूल एप्पल साइडर बीफ़ स्ट्यू की यह रेसिपी बनाएँ और यक़ीन रखें कि आपका पूरा परिवार दोबारा माँगने में देर नहीं करेगा!","10","1 कप",
["1-1/2 कप आलू","2 पाउंड स्टू के लिए बीफ़ के टुकड़े","7 बड़े चम्मच मैदा (ऑल-पर्पज़ फ्लोर)","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच थाइम","3 बड़े चम्मच कैनोला तेल","1-1/2 कप गाजर","1 कप प्याज़","1/2 कप अजवाइन (सेलरी)","1 कप सेब, छिले हुए","2 कप एप्पल साइडर","1-1/2 कप पानी","2 बड़े चम्मच एप्पल साइडर सिरका"],
["आलू को 1/2-इंच के टुकड़ों में काटें और यदि आप कम पोटैशियम वाले आहार पर हैं, तो पोटैशियम घटाने के लिए उन्हें भिगोएँ या दो बार उबालें। (विवरण उपयोगी सुझाव में देखें।)","3 बड़े चम्मच मैदा, काली मिर्च और थाइम को आपस में मिलाएँ।","बीफ़ पर मैदे का मिश्रण लपेटें।","कड़ाही में तेल गरम करें और बीफ़ के टुकड़ों को भूरा करें। अलग रख दें।","गाजर को स्लाइस करें, प्याज़, अजवाइन (सेलरी) और छिले हुए सेब को छोटे टुकड़ों में काट लें।","स्लो कुकर में सामग्री को इस क्रम में परत दर परत रखें: गाजर, उबले आलू, प्याज़, अजवाइन (सेलरी), भूरा किया बीफ़ और कटा हुआ सेब।","एप्पल साइडर, 1 कप पानी और सिरका आपस में मिलाएँ।","इसे स्लो कुकर में सामग्री पर डालें और धीमी सेटिंग पर 8 से 10 घंटे पकाएँ।","परोसने से पहले स्लो कुकर को तेज़ सेटिंग पर कर दें। बचे हुए 4 बड़े चम्मच मैदे को 1/2 कप पानी में मिलाएँ। स्ट्यू को गाढ़ा करने के लिए इसे स्लो कुकर में डालकर चलाएँ।"],
["आलू में पोटैशियम बहुत ज़्यादा होता है, लेकिन इनमें से किसी एक तरीके से आप कुछ पोटैशियम निकाल सकते हैं:","दो बार पकाने की विधि: आलू को छीलकर छोटे टुकड़ों में काटें। एक बड़े बर्तन में पानी में डालकर उबालें। पानी निथार दें और बर्तन में ताज़ा पानी डालें। उबाल आने दें, 10 मिनट पकाएँ, फिर छानकर अलग रख दें।","लीचिंग (भिगोने) की विधि: आलू को छीलकर छोटे टुकड़ों में काटें। एक बड़े बर्तन में गुनगुने नल के पानी में डालें और 2 से 4 घंटे भिगोएँ। पानी निथारकर अलग रख दें।","यदि आप पोटैशियम-सीमित आहार पर नहीं हैं, तो ऊपर वाला चरण छोड़ सकते हैं।"],
["3 मांस","1 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]),
(2919,"मैक्सिकन कोलस्लॉ","मुख्य व्यंजन को और ज़्यादा लोगों तक पहुँचाने का एक बढ़िया तरीका है उसे किसी पूरक साइड डिश के साथ जोड़ना। मैक्सिकन कोलस्लॉ एक उत्कृष्ट इज़ाफ़ा है, और कैलिफ़ोर्निया की लाबोन्टे ई. आठ लोगों के लिए अपनी ख़ास किडनी के अनुकूल रेसिपी साझा करती हैं। कतरी हुई पत्तागोभी, गाजर, शिमला मिर्च, ऑलिव ऑयल और रेड वाइन सिरका इसे सुपर-कुरकुरा-ख़ास बना देते हैं!","8","1/2 कप",
["10 औंस कोलस्लॉ मिक्स","1/4 कप हरे प्याज़","1 कप लाल शिमला मिर्च","1/2 कप ताज़ी धनिया पत्ती","1 बड़ा चम्मच हलापेनो मिर्च","3 बड़े चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","1/4 कप अनानास का रस","1/2 छोटा चम्मच पिसी अदरक","1/4 छोटा चम्मच काली मिर्च","1-1/2 छोटे चम्मच पिसा जीरा","1 बड़ा चम्मच चीनी","2 बड़े चम्मच रेड वाइन सिरका","1/3 कप मेयोनेज़"],
["हरे प्याज़, शिमला मिर्च और धनिया पत्ती को काट लें। हलापेनो मिर्च के बीज निकालकर बारीक काट लें।","एक बड़े कटोरे में कोलस्लॉ मिक्स को प्याज़, शिमला मिर्च, हलापेनो और धनिया पत्ती के साथ मिलाएँ।","एक मध्यम कटोरे में बाकी सारी सामग्री मिलाएँ और अच्छी तरह चलाएँ।","इसे पत्तागोभी के मिश्रण पर डालें और अच्छी तरह उछालकर मिलाएँ।","ढककर परोसने से पहले कम से कम 2 घंटे फ्रिज में रखें।"],
["कतरी हुई पत्तागोभी और गाजर वाला कोलस्लॉ मिक्स का पैकेट ढूँढें।","इतना बनाएँ कि कुछ बच जाए। मैक्सिकन कोलस्लॉ दूसरे दिन और भी बेहतर लगता है।","तीखी मिर्चों की मात्रा अपने स्वाद के अनुसार समायोजित करें।","प्रति सर्विंग वसा को 6 ग्राम तक घटाने के लिए कम वसा वाला मेयोनेज़ इस्तेमाल करें।"],
["1 सब्ज़ी, कम पोटैशियम","2 वसा"]),
(2920,"ठंडा पीला स्क्वैश और हल्दी का सूप","ठंडे समर स्क्वैश और हल्दी के सूप का एक ठंडा कटोरा गरमी के किसी गरम दिन भोजन की शुरुआत के लिए एकदम सही है। किडनी के अनुकूल यह स्वादिष्ट रेसिपी साल भर आपकी भूख मिटाएगी।","6","1 कप",
["4 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","2 मध्यम तोरी (ज़ुकीनी) स्क्वैश","2 मध्यम पीले क्रुकनेक स्क्वैश","1 छोटा प्याज़","1/2 कप जमे हुए हरे मटर","2 बड़े चम्मच ऑलिव ऑयल","1/2 छोटा चम्मच कोशर नमक","1/2 कप सादा वसा-रहित ग्रीक योगर्ट","2 छोटे चम्मच हल्दी"],
["तोरी, पीले स्क्वैश और प्याज़ को बड़े टुकड़ों में काट लें।","सॉसपैन में ब्रॉथ को उबालें, फिर आँच को मध्यम करें।","तोरी, पीले स्क्वैश और प्याज़ डालकर चलाएँ; 25 मिनट धीमी आँच पर पकाएँ।","हरे मटर, तेल और नमक डालें; 5 मिनट और पकाएँ।","पैन को आँच से उतारें और सूप को सामान्य तापमान तक ठंडा होने दें।","सामग्री को चिकना बनाने के लिए ब्लेंडर इस्तेमाल करें। ग्रीक योगर्ट और हल्दी मिलाकर चलाएँ।","ठंडा सूप परोसने से पहले कम से कम 6 घंटे या रातभर फ्रिज में रखें।"],
["अतिरिक्त स्वाद के लिए इनमें से कोई एक चीज़ आज़माएँ: नींबू का रस, श्रीराचा हॉट चिली सॉस, हॉट सॉस, पुदीने की पत्तियाँ, चाइव्स या जीरा।","बिना मसाले वाले जमे हुए हरे मटर ढूँढें या उनकी जगह ताज़े हरे मटर इस्तेमाल करें।","यदि उपलब्ध हो, तो सूप को सॉसपैन में ही आसानी से ब्लेंड करने के लिए इमर्शन ब्लेंडर इस्तेमाल करें।"],
["2 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]),
(2924,"चेरी कॉफ़ी केक","मिनेसोटा की डीवीटा रीनल डाइटिशियन अपनी कुछ पसंदीदा क्षेत्रीय रेसिपी साझा करती हैं, जिन्हें डायलिसिस आहार के अनुसार बदला गया है। फॉस्फोरस, पोटैशियम और सोडियम को सीमित करके डायलिसिस मरीज़ स्वादिष्ट चेरी कॉफ़ी केक की इस रेसिपी का आनंद ले सकते हैं।","24","2\" x 3\" का टुकड़ा",
["1/2 कप बिना नमक का मक्खन","2 अंडे","1 कप दानेदार चीनी","1 कप सावर क्रीम (खट्टी क्रीम)","1 छोटा चम्मच वैनिला","2 कप मैदा (ऑल-पर्पज़ व्हाइट फ्लोर)","1 छोटा चम्मच बेकिंग पाउडर","1 छोटा चम्मच बेकिंग सोडा","20 औंस चेरी पाई फ़िलिंग"],
["ओवन को 350° F पर पहले से गरम करें। मक्खन को नरम होने के लिए सामान्य तापमान पर बाहर रख दें।","मिक्सर से मक्खन, अंडे, चीनी, सावर क्रीम और वैनिला को फेंटकर क्रीमी बनाएँ।","अलग कटोरे में मैदा, बेकिंग पाउडर और बेकिंग सोडा मिलाएँ।","सूखी सामग्री को क्रीमी मक्खन के मिश्रण में डालें और अच्छी तरह मिलाएँ। घोल को चिकनाई लगे 9″ x 13″ के बेकिंग पैन में डालें।","चेरी पाई फ़िलिंग को घोल पर बराबर फैलाएँ।","सुनहरा भूरा होने तक 40 मिनट बेक करें।"],
["चाहें तो चेरी की जगह ब्लूबेरी या रास्पबेरी पाई फ़िलिंग इस्तेमाल करें।","यदि अतिरिक्त कैलोरी चाहिए, तो 24 की जगह 12 सर्विंग में काटें।","मधुमेह वाले लोगों के लिए कम चीनी के विकल्पों में बेकिंग के लिए चीनी की जगह चीनी का विकल्प इस्तेमाल करना और कम चीनी वाली चेरी फ़िलिंग इस्तेमाल करना शामिल है।"],
["1 स्टार्च","1/2 फल, कम पोटैशियम","1 वसा","1/2 उच्च कैलोरी"]),
(2925,"स्पैनिश राइस","स्पैनिश राइस की यह किडनी के अनुकूल रेसिपी आपके अगले पारिवारिक डिनर में ज़रूर हिट होगी।","6","1/2 कप",
["1/2 कप प्याज़","1/2 कप हरी शिमला मिर्च","1 बड़ा चम्मच ऑलिव ऑयल","1 कप चावल, कच्चे","1 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच चिली पाउडर","1/4 कप कम सोडियम वाली टमाटर प्यूरी","2 कप पानी"],
["प्याज़ और हरी शिमला मिर्च को काट लें।","कड़ाही में ऑलिव ऑयल में प्याज़ और हरी शिमला मिर्च को नरम होने तक भूनें।","कड़ाही में चावल डालें और चावल के हल्का भूरा होने तक लगातार चलाते रहें।","कड़ाही में लहसुन पाउडर, चिली पाउडर, टमाटर प्यूरी और पानी डालें। ढककर धीमी आँच पर चावल के नरम होने और पानी सूखने तक, लगभग 15 से 20 मिनट, पकाएँ।"],
["इसे फ़ाजिटा, एनचिलाडा या टैको की रेसिपी के साथ परोसें।"],
["1 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]),
(2926,"सौंफ और संतरे की बिस्कोटी","सौंफ और संतरे की बिस्कोटी किडनी के अनुकूल कुकी है, जिसमें सोडियम और फॉस्फोरस कम है। यह छुट्टियों के लिए एक बेहतरीन व्यंजन है, लेकिन रोज़ बनाने के लिए भी काफ़ी आसान है। इस बिस्कोटी को अपने पसंदीदा किडनी आहार वाले नाश्ते के पेय में डुबोकर आज़माएँ।","16","2 कुकीज़",
["2-1/2 कप मैदा (ऑल-पर्पज़ व्हाइट फ्लोर)","2 छोटे चम्मच बेकिंग पाउडर","2 छोटे चम्मच सौंफ़ (ऐनीज़ सीड)","1 छोटा चम्मच कद्दूकस किया संतरे का छिलका","1/2 कप चीनी","2 बड़े अंडे","1/4 कप कैनोला तेल","1 छोटा चम्मच ऑरेंज एक्सट्रैक्ट"],
["ओवन को 350°F पर पहले से गरम करें। एक बड़ी कुकी शीट पर पार्चमेंट पेपर बिछाएँ।","पहली पाँच सूखी सामग्री को एक बड़े कटोरे में मिलाएँ और अच्छी तरह चलाएँ।","अंडे, तेल और एक्सट्रैक्ट को एक छोटे कटोरे में डालकर झागदार होने तक फेंटें, चाहे हाथ से व्हिस्क से या इलेक्ट्रिक मिक्सर से लगभग 30 सेकंड।","तरल मिश्रण को सूखी सामग्री में डालें। लकड़ी के चम्मच से आटा बनने तक मिलाएँ। आटा भुरभुरा रहेगा।","आटे को हल्के मैदा लगे पटले पर रखें। गोला बनाएँ और कई बार गूँधें। गोले को आधा काट लें।","हर आधे हिस्से को लगभग 10 इंच लंबे लट्ठे में बेल लें। ऊपर से थोड़ा दबाकर चपटा करें।","आटे को कुकी शीट पर रखें और हल्का सुनहरा होने तक, लगभग 15 से 20 मिनट, बेक करें।","ओवन से निकालें। 10 मिनट ठंडा होने दें। दाँतेदार चाकू से लगभग 2/3-इंच की दूरी पर स्लाइस करें, ताकि आटे के हर आधे हिस्से से 16 बिस्कोटी मिलें।","कटी हुई बिस्कोटी को कटी हुई तरफ़ ऊपर करके वापस कुकी शीट पर रखें और हल्का सुनहरा होने तक, लगभग 5 मिनट, बेक करें। ओवन से निकालें, बिस्कोटी को पलटें और 5 मिनट बेक करें। ओवन से निकालकर रैक पर ठंडा करें।"],
["हवाबंद डिब्बे में 2 हफ़्ते तक रखें या फ्रीज़ करें।","बिस्कोटी को दो बार बेक किया जाता है ताकि कठोर कुकी बने, जिसे कॉफ़ी, चाय या पसंदीदा पेय में डुबोया जा सके।","पारंपरिक बिस्कोटी केवल सौंफ़ (ऐनीज़ सीड) से बनती है; हालाँकि, आजकल कई \"गॉरमे\" संस्करण हैं जिनमें अलग-अलग सूखे फल और/या मेवे होते हैं। ध्यान रखें कि मेवों में फॉस्फोरस और पोटैशियम ज़्यादा होता है; फिर भी कम मात्रा डाली जा सकती है।","क्रैनबेरी-संतरा-पिस्ता बिस्कोटी के लिए, सौंफ़ न डालें और 1 कप सूखी क्रैनबेरी और 1/4 कप बारीक कटे बिना नमक वाले पिस्ता डालें।","ब्लूबेरी बिस्कोटी के लिए, सौंफ़ और संतरे का छिलका न डालें, ऑरेंज एक्सट्रैक्ट की जगह 2 छोटे चम्मच वैनिला एक्सट्रैक्ट इस्तेमाल करें और 3/4 कप सूखी ब्लूबेरी डालें।"],
["1 स्टार्च"]),
(2927,"ब्लैकनिंग सीज़निंग","ब्लैकनिंग सीज़निंग किसी भी समुद्री भोजन या पोल्ट्री व्यंजन में तीखा स्वाद भर देती है, जबकि बाज़ार के तुलनीय ब्रांड की तुलना में सोडियम बहुत कम रखती है।","16","1 छोटा चम्मच",
["2 बड़े चम्मच पैपरिका","1 बड़ा चम्मच सूखी थाइम","2 छोटे चम्मच पिसा ओरेगैनो","1 बड़ा चम्मच लाल मिर्च (काएन पेपर)","1 छोटा चम्मच काली मिर्च","1 छोटा चम्मच सफ़ेद मिर्च","1 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच नमक"],
["सामग्री को आपस में मिलाएँ।","इस्तेमाल होने तक हवाबंद डिब्बे में रखें।"],
["ब्लैकनिंग सीज़निंग मछली, झींगा या चिकन पर बहुत अच्छी लगती है।","पूरी तरह सोडियम-मुक्त सीज़निंग के लिए नमक न डालें।","अपने पसंदीदा समुद्री भोजन या पोल्ट्री व्यंजन के लिए रब या सीज़निंग के रूप में इस्तेमाल करते समय प्रति सर्विंग 1 छोटा चम्मच लें।"],
["कोई नहीं"]),
(2930,"मैंडेरिन चिकन सलाद","अपने अगले दोपहर या रात के खाने के लिए किडनी के अनुकूल रेसिपी मैंडेरिन चिकन सलाद का आनंद लें।","8","1/2 कप",
["1-1/2 पाउंड बिना हड्डी और बिना त्वचा वाला चिकन ब्रेस्ट, कच्चा","2 हरे प्याज़","2 डंठल अजवाइन (सेलरी)","3 मध्यम मैंडेरिन संतरे","1/2 कप कम वसा वाला मेयोनेज़"],
["ओवन को 350° F पर पहले से गरम करें।","चिकन को बेकिंग पैन में सजाएँ और पकने तक, लगभग 45 मिनट, बेक करें। पके चिकन को ओवन से निकालें और ठंडा होने दें।","चिकन को बारीक टुकड़ों में काटकर बड़े कटोरे में रखें। हरे प्याज़ और अजवाइन (सेलरी) को बारीक काट लें। मैंडेरिन संतरे का छिलका उतारें।","चिकन में हरे प्याज़, अजवाइन (सेलरी) और मेयोनेज़ डालें। अच्छी तरह मिलाएँ। परोसने तक ठंडा रखें।","परोसने से पहले मैंडेरिन संतरे की फाँकों को आधा काटें और चिकन सलाद में धीरे से मिला दें।"],
["इसे मिक्स्ड सलाद पत्तों पर परोसें, ब्रेड या रोल पर सैंडविच के रूप में परोसें, या उच्च प्रोटीन नाश्ते के लिए क्रैकर पर स्प्रेड की तरह लगाएँ।","यदि ताज़ा फल उपलब्ध न हो, तो उसकी जगह 1 कप पानी निथारे डिब्बाबंद मैंडेरिन संतरे इस्तेमाल करें।","उच्च प्रोटीन आहार वाले लोगों के लिए इस रेसिपी में प्रोटीन की मात्रा बढ़ाने के लिए 1/4 कप प्रोटीन पाउडर मिलाया जा सकता है।","यदि आप कम प्रोटीन वाले आहार पर हैं, तो आपको अपनी भोजन योजना के अनुसार हिस्से का आकार घटाना पड़ सकता है। मदद के लिए अपने डाइटिशियन से सलाह लें।"],
["3 मांस"]),
(2934,"क्रीमी झींगा और ब्रोकली फेटुचिनी","कोलोराडो की डीवीटा रीनल डाइटिशियन जीन क्रीमी झींगा और ब्रोकली फेटुचिनी की अपनी शानदार, किडनी के अनुकूल रेसिपी साझा करती हैं। चपटे पास्ता नूडल्स को हाफ एंड हाफ और क्रीम चीज़ से बने क्रीमी सॉस में लपेटा जाता है, जिसमें लहसुन, नींबू का रस, हरी काली मिर्च के दाने और लाल शिमला मिर्च का स्वाद है। स्वादिष्ट झींगा और कुरकुरी ब्रोकली इस लुभावने मुख्य व्यंजन को पूरा करते हैं।","4","1-1/4 कप",
["4 औंस फेटुचिनी, कच्ची","1-3/4 कप ब्रोकली के फूल","3/4 पाउंड जमे हुए मध्यम झींगे","1 कली लहसुन","10 औंस क्रीम चीज़","1/2 छोटा चम्मच लहसुन पाउडर","1/4 कप नींबू का रस","3/4 छोटा चम्मच पिसी काली मिर्च के दाने","1/4 कप हाफ एंड हाफ क्रीमर","1/4 कप लाल शिमला मिर्च"],
["पास्ता को निर्देशों के अनुसार, नमक डाले बिना पकाएँ।","पकाने के आख़िरी 3 मिनट में ब्रोकली डालें। पानी निथार दें। गरम रखें।","बड़ी नॉनस्टिक कड़ाही में मध्यम आँच पर झींगे और लहसुन को 2 से 3 मिनट तक, झींगे के अंदर तक गरम होने तक, पकाएँ और चलाएँ।","क्रीम चीज़, लहसुन पाउडर, नींबू का रस, पिसी काली मिर्च के दाने और हाफ एंड हाफ डालें। 2 मिनट पकाएँ और चलाएँ।","पास्ता और झींगे के मिश्रण को मिलाएँ। ऊपर से शिमला मिर्च छिड़कें।"],
["झींगे की जगह 3/4 पाउंड ताज़ी, बिना हड्डी के चिकन की पट्टियाँ, 6 मिनट पकाकर, इस्तेमाल की जा सकती हैं।","वसा को 15 ग्राम तक घटाने के लिए कम वसा वाला क्रीम चीज़ इस्तेमाल करें, हालाँकि सोडियम बढ़कर प्रति सर्विंग 466 मिग्रा हो जाता है।","फॉस्फेट एडिटिव के बिना हाफ एंड हाफ या नॉन-डेयरी क्रीमर ढूँढें।"],
["3 मांस","1-1/2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","1/2 डेयरी","2 वसा"]),
(2935,"हॉट क्रैब डिप","यहाँ एक ऐसा ऐपेटाइज़र है जो पार्टी का सितारा बनने वाला है, डीवीटा डाइटिशियन जैनिस की हॉट क्रैब डिप। मज़ेदार, स्वादिष्ट और भीड़ को सचमुच खुश करने वाली, यह किडनी के अनुकूल डिप आप इसे किसी भी आयोजन में लाएँ तो आपके पता चलने से पहले ही ख़त्म हो जाएगी।","10","3 बड़े चम्मच",
["8 औंस क्रीम चीज़","1 बड़ा चम्मच प्याज़","1 छोटा चम्मच नींबू का रस","2 छोटे चम्मच वूस्टरशायर सॉस","1/8 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच लाल मिर्च (काएन पेपर)","2 बड़े चम्मच 1% कम वसा वाला दूध","6 औंस डिब्बाबंद केकड़े का मांस"],
["ओवन को 375º F पर पहले से गरम करें। क्रीम चीज़ को नरम होने के लिए बाहर रख दें। प्याज़ को बहुत बारीक काट लें।","नरम क्रीम चीज़ को एक कटोरे में रखें।","प्याज़, नींबू का रस, वूस्टरशायर सॉस, काली मिर्च और लाल मिर्च (काएन पेपर) डालें। अच्छी तरह मिलाएँ। दूध डालकर चलाएँ।","केकड़े का मांस डालें और मिलने तक चलाएँ।","मिश्रण को ओवन-सुरक्षित डिश में रखें। बिना ढके 15 मिनट या गरम और बुलबुलेदार होने तक बेक करें।"],
["गरमागरम कम सोडियम वाले क्रैकर के साथ परोसें।","इस रेसिपी को डिब्बाबंद केकड़े की जगह ताज़े भाप में पके केकड़े के मांस के साथ आज़माएँ।","कम वसा वाले क्रीम चीज़ का इस्तेमाल करके प्रति सर्विंग वसा को 4 ग्राम तक घटाएँ। ध्यान रखें, सोडियम की मात्रा ज़्यादा होती है।"],
["1 मांस","1/2 वसा"]),
(2937,"हनी मस्टर्ड डिपिंग सॉस","हनी मस्टर्ड डिपिंग सॉस चिकन या मछली के नगेट्स के लिए किडनी के अनुकूल डिपिंग सॉस के रूप में बढ़िया है, या इसे स्वादिष्ट सलाद ड्रेसिंग के रूप में भी बनाया जा सकता है।","14","1 बड़ा चम्मच",
["1 बड़ा चम्मच डिजॉन मस्टर्ड","1/2 कप मेयोनेज़","1/3 कप शहद","2 छोटे चम्मच वूस्टरशायर सॉस"],
["मस्टर्ड, मेयोनेज़, शहद और वूस्टरशायर सॉस को एक छोटे कटोरे में मिलाकर चलाएँ।","परोसने तक सॉस को फ्रिज में ठंडा करें।"],
["इसे चिकन या मछली के नगेट्स के लिए डिपिंग सॉस के रूप में इस्तेमाल करें, या सलाद ड्रेसिंग के रूप में उपयोग करें।"],
["1 वसा","1/2 उच्च कैलोरी"]),
(2938,"गार्लिक पिटा चिप्स","गार्लिक पिटा चिप्स में केवल 4 सामग्री हैं और ये बनाने में आसान हैं। विविधता के लिए अपना पसंदीदा बिना नमक वाला सीज़निंग ब्लेंड डालें।","6","8 चिप्स",
["6 सफ़ेद पिटा ब्रेड, बड़ी 8-इंच की","1/4 कप ऑलिव ऑयल","1/2 छोटा चम्मच काली मिर्च","1/2 बड़ा चम्मच लहसुन पाउडर"],
["ओवन को 400° F पर पहले से गरम करें। बेकिंग शीट पर पार्चमेंट पेपर बिछाएँ।","हर पिटा ब्रेड को 8 तिकोने टुकड़ों में काटें और बेकिंग शीट पर रखें।","एक छोटे कटोरे में तेल, काली मिर्च और लहसुन पाउडर मिलाएँ।","पेस्ट्री ब्रश से हर पिटा तिकोने के ऊपर तेल का मिश्रण लगाएँ।","6 से 8 मिनट या हल्का भूरा और कुरकुरा होने तक बेक करें। आनंद लें!"],
["पिटा चिप्स को हवाबंद डिब्बे में एक हफ़्ते तक रखें।","यदि पतले चिप्स चाहिए, तो हर पिटा तिकोने को एक परत में अलग करें और बेक करने से पहले उस पर ऑलिव ऑयल का मिश्रण लगाएँ।","विविधता के लिए लहसुन पाउडर की जगह अपना पसंदीदा बिना नमक वाला सीज़निंग ब्लेंड इस्तेमाल करें।","चिप्स को अपनी पसंदीदा किडनी के अनुकूल डिप के साथ परोसें।","सबसे कम सोडियम वाली पिटा ब्रेड ढूँढें।"],
["2 स्टार्च","1-1/2 वसा"]),
(2941,"ब्रोकली और बीफ़ स्टर-फ्राई","अब आप डीवीटा डाइटिशियन त्रिशा और उनके ब्रोकली और बीफ़ स्टर-फ्राई के किडनी के अनुकूल संस्करण की बदौलत घर पर चाइनीज़ रेस्तरां शैली का डिनर कर सकते हैं। इसमें रेस्तरां के व्यंजन की तुलना में सोडियम बहुत कम है, साथ ही आप अपनी भोजन योजना की प्रोटीन आवश्यकता पूरी करने के लिए बीफ़ की मात्रा आसानी से समायोजित कर सकते हैं।","4","1-1/2 कप स्टर-फ्राई + 1/2 कप चावल",
["2 कलियाँ लहसुन","1 मध्यम रोमा टमाटर","8 औंस दुबला सर्लोइन बीफ़, कच्चा","12 औंस जमे हुए ब्रोकली स्टर-फ्राई सब्ज़ी मिश्रण","2 बड़े चम्मच मूँगफली का तेल","1/4 कप कम सोडियम वाला चिकन ब्रॉथ","1 बड़ा चम्मच कॉर्नस्टार्च","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","2 कप पके हुए ब्राउन या सफ़ेद चावल"],
["लहसुन की कलियों और रोमा टमाटर को काट लें। बीफ़ को पतली पट्टियों में काटें।","जमे हुए स्टर-फ्राई सब्ज़ी मिश्रण को माइक्रोवेव में डीफ़्रॉस्ट सेटिंग पर 3-4 मिनट पिघलाएँ।","फ्राई पैन या वोक में तेल गरम करें और लहसुन को खुशबू आने तक भूनें। सब्ज़ी मिश्रण डालें और पकने तक, लगभग 5 मिनट, स्टर-फ्राई करें। पैन से निकालकर अलग रख दें।","उसी पैन में बीफ़ डालें। बीफ़ को अपनी पसंद के अनुसार पकने तक, लगभग 7 मिनट, पकाएँ।","चिकन ब्रॉथ, कॉर्नस्टार्च और सोया सॉस को एक कटोरे में मिलाकर सॉस तैयार करें।","पके हुए सब्ज़ियाँ, सॉस और टमाटर को बीफ़ वाले पैन में डालें। सॉस के गाढ़ा होने तक गरम करें और चलाएँ।","व्यंजन को 1/2 कप चावल के साथ परोसें।"],
["ब्रोकली स्टर-फ्राई मिश्रण में 4-6 सब्ज़ियों का मिश्रण होता है। ब्रोकली के अलावा मिश्रण में शिमला मिर्च, प्याज़, मशरूम और वॉटर चेस्टनट, गाजर, अजवाइन (सेलरी), शुगर स्नैप मटर या बेबी कॉर्न हो सकते हैं।","चाहें तो जमी हुई सब्ज़ियों की जगह ताज़ी सब्ज़ियाँ इस्तेमाल करें। इसके लिए 3 कप ताज़ी ब्रोकली के फूल, 1/2 लाल शिमला मिर्च, 1/2 कप स्नो पीज़ और 1/4 कप डिब्बाबंद कटे वॉटर चेस्टनट इस्तेमाल करें।","विश्लेषण में ब्राउन राइस शामिल है। अपनी पसंद के अनुसार ब्राउन, सफ़ेद या वाइल्ड राइस चुनें।","ज़्यादा प्रोटीन वाले भोजन के लिए मांस बढ़ाएँ।","इस व्यंजन में बदलाव के लिए आप बीफ़ की जगह चिकन या झींगा इस्तेमाल कर सकते हैं।"],
["2 मांस","1-1/2 स्टार्च","2 सब्ज़ी, उच्च पोटैशियम","1 वसा"]),
(2942,"हर्ब सॉस मिक्स","किडनी के अनुकूल हर्ब सॉस मिक्स की इस रेसिपी से अपने मुख्य व्यंजन में तीखापन लाएँ। इस मिक्स में काली मिर्च, लहसुन पाउडर, अजवाइन का नमक, अजवाइन के बीज, सूखी सरसों और पैपरिका जैसी जड़ी-बूटियाँ और मसाले शामिल हैं।","6","चिकन, मछली या पोर्क की हर सर्विंग के लिए मिश्रण का 1/2 बड़ा चम्मच।",
["1 छोटा चम्मच काली मिर्च","2 छोटे चम्मच लहसुन पाउडर","1/2 छोटा चम्मच अजवाइन का नमक (सेलरी सॉल्ट)","1 छोटा चम्मच अजवाइन के बीज","2-1/2 छोटे चम्मच सूखी सरसों (ड्राई मस्टर्ड)","2 छोटे चम्मच हंगेरियन पैपरिका"],
["सारी सामग्री को मिलाएँ और हवाबंद डिब्बे में रखें।","मांस के एक हिस्से के लिए सॉस तैयार करने के लिए, 1 बड़ा चम्मच बिना नमक का मक्खन या ऑलिव ऑयल पिघलाएँ और 1/2 बड़ा चम्मच हर्ब सॉस मिक्स डालें।","इसे मांस के ऊपर डालें और ओवन में बेक करें या बीफ़, चिकन या मछली पर सॉस टॉपिंग के रूप में इस्तेमाल करें।"],
["हंगेरियन पैपरिका अपने मीठे स्वाद के लिए जानी जाती है। स्मोक्ड पैपरिका को विकल्प के रूप में इस्तेमाल न करें।","विविधता के लिए चिली पाउडर, प्याज़ पाउडर या पोल्ट्री सीज़निंग जैसे दूसरे मसाले आज़माएँ।","अपना हर्ब सॉस खुद बनाकर पैसे बचाएँ।","अजवाइन का नमक न डालकर सोडियम-मुक्त संस्करण बनाएँ।"],
["कोई नहीं"]),
(2947,"ग्रिल्ड फ्लैंक स्टेक और विनेग्रेट सब्ज़ियाँ","कैलिफ़ोर्निया की डीवीटा रीनल डाइटिशियन लिसा अपनी मरीज़ चार्लीन की दी हुई रेसिपी साझा करती हैं, जो स्वादिष्ट और पूरे परिवार को पसंद आने वाले एक-बर्तन वाले भोजन की हैं। ग्रिल जलाएँ और किडनी के अनुकूल ग्रिल्ड फ्लैंक स्टेक और विनेग्रेट सब्ज़ियों का आनंद लें","4","3 औंस स्टेक और सब्ज़ियों का 1/4 हिस्सा",
["1 पाउंड फ्लैंक स्टेक","1/2 छोटा चम्मच नमक","1 छोटा चम्मच काली मिर्च","1 मध्यम बैंगन","2 मध्यम शिमला मिर्च","6 बड़े चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","2 बड़े चम्मच बालसेमिक सिरका","1 कली लहसुन","1/4 कप ताज़ा फ्लैट-लीफ़ अजमोद (पार्सले)"],
["ग्रिल को तेज़-मध्यम आँच पर गरम करें।","स्टेक पर 1/4 छोटा चम्मच नमक और 1/2 छोटा चम्मच काली मिर्च लगाएँ।","मनचाहे पकाव तक ग्रिल करें; मीडियम-रेयर के लिए हर तरफ़ 4 से 5 मिनट।","इसे कटिंग बोर्ड पर रखें और स्लाइस करने से पहले कम से कम 5 मिनट आराम करने दें।","जब स्टेक पक रहा हो, तब बैंगन को चार 1/2″ मोटे गोल स्लाइस में काटें और शिमला मिर्च को चार हिस्सों में काटकर बीज निकाल दें।","बैंगन और शिमला मिर्च दोनों तरफ़ 3 बड़े चम्मच तेल ब्रश से लगाएँ। 1/4 छोटा चम्मच नमक और 1/2 छोटा चम्मच काली मिर्च छिड़कें।","नरम होने तक, हर तरफ़ 4 से 5 मिनट, ग्रिल करें।","लहसुन की कली को बारीक काटें और अजमोद (पार्सले) काट लें। एक छोटे कटोरे में बचा तेल, सिरका, लहसुन और अजमोद (पार्सले) मिलाकर विनेग्रेट सॉस बनाएँ।","स्टेक और सब्ज़ियों को 4 डिनर प्लेटों में बाँट दें।","सॉस को सब्ज़ियों पर चम्मच से डालें या अलग से परोसें।"],
["बचे हुए से सैंडविच बनाएँ।","कम प्रोटीन वाले आहार के लिए अपनी भोजन योजना के अनुसार स्टेक का हिस्सा समायोजित करें।","फ्लैंक स्टेक को लंदन ब्रॉइल भी कहा जाता है।"],
["3 मांस","2 सब्ज़ी, कम पोटैशियम","2 वसा"]),
]
